# cache-busting: /assets/* is cached for a week at the edge, so every reference carries a content hash
import hashlib as _h,glob as _g,re as _r
_V={}
for _f in _g.glob("dist/assets/**/*",recursive=True):
    if os.path.isfile(_f) and not _f.endswith(".gz"):_V[_f[len("dist"):]]=_h.sha256(open(_f,"rb").read()).hexdigest()[:10]
_pat=_r.compile(r"(/assets/[\w./-]+?\.(?:js|mjs|css|wasm))(?![\w?])")
for _f in _g.glob("dist/**/*.html",recursive=True)+[x for x in _g.glob("dist/assets/**/*.js",recursive=True) if "/tess/" not in x]:
    _s=open(_f,encoding="utf-8").read();_n=_pat.sub(lambda m:m.group(1)+"?v="+_V[m.group(1)] if m.group(1) in _V else m.group(1),_s)
    if _n!=_s:open(_f,"w",encoding="utf-8").write(_n)
print("cache-busted",len(_V),"assets")

